"use client"

import { useState, useEffect } from "react"
import axios from "axios"
import { AlertCircle, Loader2, CheckCircle, Calendar } from "lucide-react"
import Layout from "./Layout"

export default function MealsForNextDay() {
  const [meals, setMeals] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [error, setError] = useState("")
  const [success, setSuccess] = useState("")
  const [isConfirmed, setIsConfirmed] = useState(false)
  const [optedOutMeals, setOptedOutMeals] = useState([])
  const [isAbsent, setIsAbsent] = useState(false)

  useEffect(() => {
    fetchMealsForNextDay()
    fetchNextDayOptOuts()
    checkConfirmationStatus()
    checkAbsenceStatus()
  }, [])

  const fetchMealsForNextDay = async () => {
    setIsLoading(true)
    setError("")
    const token = localStorage.getItem("token")

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/meals/next-day`, {
        headers: { Authorization: `Bearer ${token}`, Role: "intern" },
      })
      setMeals(response.data || [])
    } catch (err) {
      setError("Erreur lors de la récupération des repas de demain : " + (err.response?.data?.message || err.message))
    } finally {
      setIsLoading(false)
    }
  }

  const fetchNextDayOptOuts = async () => {
    const token = localStorage.getItem("token")
    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/meals/next-day-opt-outs`, {
        headers: { Authorization: `Bearer ${token}`, Role: "intern" },
      })
      setOptedOutMeals(response.data.optedOutMeals || [])
    } catch (err) {
      console.error("Erreur lors de la récupération des repas non bénéficiés :", err)
      setOptedOutMeals([])
    }
  }

  const checkConfirmationStatus = () => {
    const confirmedDate = localStorage.getItem("chefConfirmationDate")
    if (confirmedDate) {
      const today = new Date().toDateString()
      if (new Date(confirmedDate).toDateString() === today) {
        setIsConfirmed(true)
      } else {
        localStorage.removeItem("chefConfirmationDate")
        setIsConfirmed(false)
      }
    }
  }

  const checkAbsenceStatus = async () => {
    const token = localStorage.getItem("token")
    const tomorrow = new Date()
    tomorrow.setDate(tomorrow.getDate() + 1)
    tomorrow.setHours(0, 0, 0, 0)

    try {
      const response = await axios.get(`${process.env.REACT_APP_API_URL}/api/absence/my-absences`, {
        headers: { Authorization: `Bearer ${token}`, Role: "intern" },
      })
      const absences = response.data.data || []
      const isAbsentTomorrow = absences.some((absence) => {
        const start = new Date(absence.startDate)
        const end = new Date(absence.endDate)
        return absence.status === "approved" && start <= tomorrow && end >= tomorrow
      })
      setIsAbsent(isAbsentTomorrow)
    } catch (err) {
      console.error("Erreur lors de la vérification des absences :", err)
      setIsAbsent(false)
    }
  }

  const handleOptOut = async (mealId, mealType) => {
    if (
      window.confirm(
        `Êtes-vous sûr de vouloir vous désinscrire du ${mealType === "Breakfast" ? "Petit-déjeuner" : mealType === "Lunch" ? "Déjeuner" : "Dîner"} de demain ?`,
      )
    ) {
      setError("")
      setSuccess("")
      const token = localStorage.getItem("token")
      const tomorrow = new Date()
      tomorrow.setDate(tomorrow.getDate() + 1)
      tomorrow.setHours(0, 0, 0, 0)

      try {
        await axios.post(
          `${process.env.REACT_APP_API_URL}/api/meals/opt-out`,
          { date: tomorrow, mealTypes: [mealType] },
          { headers: { Authorization: `Bearer ${token}`, Role: "intern" } },
        )
        setSuccess(
          `Vous vous êtes désinscrit(e) du ${mealType === "Breakfast" ? "Petit-déjeuner" : mealType === "Lunch" ? "Déjeuner" : "Dîner"} avec succès !`,
        )
        const mealToAdd = meals.find((meal) => meal._id === mealId)
        if (mealToAdd) {
          setOptedOutMeals((prev) => [...prev, mealToAdd])
        }
      } catch (err) {
        setError("Erreur lors de la désinscription : " + (err.response?.data?.message || err.message))
      }
    }
  }

  const handleOptIn = async (mealId, mealType) => {
    if (
      window.confirm(
        `Voulez-vous vous réinscrire au ${mealType === "Breakfast" ? "Petit-déjeuner" : mealType === "Lunch" ? "Déjeuner" : "Dîner"} de demain ?`,
      )
    ) {
      setError("")
      setSuccess("")
      const token = localStorage.getItem("token")
      const tomorrow = new Date()
      tomorrow.setDate(tomorrow.getDate() + 1)
      tomorrow.setHours(0, 0, 0, 0)

      try {
        await axios.post(
          `${process.env.REACT_APP_API_URL}/api/meals/opt-in`,
          { date: tomorrow, mealType },
          { headers: { Authorization: `Bearer ${token}`, Role: "intern" } },
        )
        setSuccess(
          `Vous vous êtes réinscrit(e) au ${mealType === "Breakfast" ? "Petit-déjeuner" : mealType === "Lunch" ? "Déjeuner" : "Dîner"} avec succès !`,
        )
        setOptedOutMeals((prev) => prev.filter((meal) => meal._id !== mealId))
      } catch (err) {
        setError("Erreur lors de la réinscription : " + (err.response?.data?.message || err.message))
      }
    }
  }

  const getMealTypeName = (type) => {
    switch (type) {
      case "Breakfast":
        return "Petit-déjeuner"
      case "Lunch":
        return "Déjeuner"
      case "Dinner":
        return "Dîner"
      default:
        return type
    }
  }

  return (
    <Layout>
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-4 sm:py-8">
        <div className="bg-white rounded-2xl shadow-xl overflow-hidden border border-[#C8A45D/30]/50">
          <div className="bg-gradient-to-r from-[#00717F] to-[#C8A45D] text-white p-4 sm:p-6 flex items-center">
            <div className="bg-white/10 p-2 sm:p-3 rounded-full mr-3 sm:mr-4">
              <Calendar className="h-6 w-6 sm:h-8 sm:w-8" />
            </div>
            <div>
              <h2 className="text-xl sm:text-2xl font-bold tracking-tight">Repas de Demain</h2>
              <p className="text-white/80 mt-1 text-xs sm:text-sm">Liste des repas prévus pour le lendemain</p>
            </div>
          </div>

          {(error || success) && (
            <div
              className={`p-3 sm:p-4 m-3 sm:m-4 rounded-r-md ${
                error ? "bg-red-50 border-l-4 border-red-500" : "bg-green-50 border-l-4 border-green-500"
              } flex items-center gap-3`}
            >
              {error ? (
                <AlertCircle className="h-5 w-5 text-red-500 flex-shrink-0" />
              ) : (
                <CheckCircle className="h-5 w-5 text-green-500 flex-shrink-0" />
              )}
              <p className={`text-xs sm:text-sm ${error ? "text-red-700" : "text-green-700"}`}>{error || success}</p>
            </div>
          )}

          <div className="p-4 sm:p-6">
            {isLoading ? (
              <div className="flex justify-center items-center h-48 sm:h-64">
                <div className="flex flex-col items-center gap-2">
                  <Loader2 className="h-8 w-8 sm:h-10 sm:w-10 text-[#00717F] animate-spin" />
                  <p className="text-[#00717F] text-xs sm:text-sm font-medium">Chargement des repas...</p>
                </div>
              </div>
            ) : meals.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-48 sm:h-64 text-gray-500">
                <Calendar className="h-10 w-10 sm:h-12 sm:w-12 text-gray-300 mb-3" />
                <p className="text-center text-sm sm:text-base">Aucun repas prévu pour demain.</p>
              </div>
            ) : (
              <ul className="space-y-3 sm:space-y-4">
                {meals.map((meal) => {
                  const isOptedOut = optedOutMeals.some((optedOutMeal) => optedOutMeal._id === meal._id) || isAbsent
                  const isDisabled = isConfirmed || isAbsent
                  const buttonClass = isDisabled
                    ? "bg-gray-400 cursor-not-allowed"
                    : isOptedOut
                      ? "bg-green-600 hover:bg-green-700"
                      : "bg-[#00717F] hover:bg-[#C8A45D]"

                  return (
                    <li
                      key={meal._id}
                      className="flex flex-col sm:flex-row justify-between items-start sm:items-center p-3 sm:p-4 bg-gray-50 rounded-xl hover:bg-[#F5F6FA]/30 transition-colors duration-150 gap-3 sm:gap-0"
                    >
                      <div>
                        <p className="text-sm font-medium text-gray-900">
                          {meal.mealName} ({getMealTypeName(meal.type)})
                        </p>
                        <p className="text-xs sm:text-sm text-gray-500">
                          Date: {new Date(meal.date).toLocaleDateString("fr-FR")}
                        </p>
                        {isAbsent && (
                          <p className="text-xs sm:text-sm text-red-600 mt-1">Vous êtes absent ce jour-là</p>
                        )}
                      </div>
                      <button
                        onClick={() =>
                          isOptedOut ? handleOptIn(meal._id, meal.type) : handleOptOut(meal._id, meal.type)
                        }
                        disabled={isDisabled}
                        className={`px-3 py-1.5 sm:px-4 sm:py-2 rounded-md text-white text-xs sm:text-sm font-medium ${buttonClass} transition-colors w-full sm:w-auto text-center`}
                      >
                        {isAbsent ? "S'inscrire" : isOptedOut ? "S'inscrire" : "Se Désinscrire"}
                      </button>
                    </li>
                  )
                })}
              </ul>
            )}
          </div>
        </div>
      </div>
    </Layout>
  )
}
